// Single clean Zod schema mapping to properties required


export type AuditAnimationProps = Record<string, any>;

const AuditAnimation: React.FC<AuditAnimationProps> = ({
  backgroundColor = "#0F172A",
  transparentBackground = false,
  durationInSeconds = 11,
  accentColor = "#D2FF03",
  titleText = "Audits are built for the old world:",
  point1Text = "endless evidence folders",
  point2Text = "buying templates",
  point3Text = "last minute scrambles",
  point4Text = "and staff guessing what auditors look for",
  slide2Text1 = "but providers need *something more*",
  slide2Text2 = "you need a *platform that never sleeps*",
  cardBgColor = "#1E293B",
  cardBorderColor = "#334155",
  textColor = "#F1F5F9",
  titleColor = "#FFFFFF",
  accentGlow = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const slideTransitionStart = totalFrames * 0.48;
  const slideTransitionEnd = totalFrames * 0.54;

  // Custom helper to dynamically fetch snappy spring properties
  const getCustomSpring = (startFrame: number) => {
    return spring({
      frame: Math.max(0, frame - startFrame),
      fps,
      config: {
        damping: 15,
        mass: 0.6,
        stiffness: 100,
      },
    });
  };

  // Slide 1 Entrance Animations
  const title1Spring = getCustomSpring(10);
  const title1Opacity = interpolate(title1Spring, [0, 1], [0, 1]);
  const title1TranslateY = interpolate(title1Spring, [0, 1], [30, 0]);

  // Slowed down the timing between points (previously 12 frame increments, now 20 frame increments)
  const p1Spring = getCustomSpring(30);
  const p2Spring = getCustomSpring(50);
  const p3Spring = getCustomSpring(70);
  const p4Spring = getCustomSpring(90);

  // Dynamic interpolation for Slide 1 Exit (Slide up and out)
  const slide1ExitY = interpolate(
    frame,
    [slideTransitionStart, slideTransitionEnd],
    [0, -height],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const slide1ExitOpacity = interpolate(
    frame,
    [slideTransitionStart, slideTransitionEnd],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Dynamic interpolation for Slide 2 Entrance
  const slide2EntryY = interpolate(
    frame,
    [slideTransitionStart, slideTransitionEnd],
    [height * 0.4, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const slide2EntryOpacity = interpolate(
    frame,
    [slideTransitionStart, slideTransitionEnd],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Slide 2 Content Staggering
  const s2Line1Spring = getCustomSpring(slideTransitionEnd + 10);
  const s2Line1Scale = interpolate(s2Line1Spring, [0, 1], [0.9, 1]);
  const s2Line1Opacity = interpolate(s2Line1Spring, [0, 1], [0, 1]);

  const s2Line2Spring = getCustomSpring(slideTransitionEnd + 45);
  const s2Line2Scale = interpolate(s2Line2Spring, [0, 1], [0.9, 1]);
  const s2Line2Opacity = interpolate(s2Line2Spring, [0, 1], [0, 1]);

  const bgColorValue = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Render text containing custom highlighting logic with character splitting
  const renderHighlightedText = (text: string) => {
    return text.split("*").map((part, idx) => {
      const isHighlighted = idx % 2 === 1;
      return (
        <span
          key={idx}
          style={{
            color: isHighlighted ? accentColor : titleColor,
            fontWeight: isHighlighted ? "800" : "700",
            transition: "none",
          }}
        >
          {part}
        </span>
      );
    });
  };

  // Standard box metrics mapped out cleanly - Made larger on first slide
  const renderBox = (
    text: string,
    IconComp: React.FC<{ size: number; color: string }>,
    springValue: number
  ) => {
    const boxOpacity = interpolate(springValue, [0, 1], [0, 1]);
    const boxScale = interpolate(springValue, [0, 1], [0.93, 1]);
    const boxTranslateX = interpolate(springValue, [0, 1], [50, 0]);

    return (
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          backgroundColor: cardBgColor,
          border: `1px solid ${cardBorderColor}`,
          borderLeft: `6px solid ${accentColor}`,
          borderRadius: 20,
          padding: "32px 36px",
          width: "100%",
          boxShadow: "0 15px 35px -5px rgba(0, 0, 0, 0.3)",
          opacity: boxOpacity,
          transform: `scale(${boxScale}) translateX(${boxTranslateX}px)`,
          transition: "none",
        }}
      >
        <div
          style={{
            width: 72,
            height: 72,
            borderRadius: "50%",
            backgroundColor: `${accentColor}1A`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            marginRight: 28,
            border: `1px solid ${accentColor}33`,
            transition: "none",
          }}
        >
          <IconComp size={36} color={accentColor} />
        </div>
        <div
          style={{
            fontSize: 34,
            fontWeight: "600",
            color: textColor,
            lineHeight: "1.3",
            transition: "none",
          }}
        >
          {text}
        </div>
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColorValue,
        fontFamily,
        color: textColor,
        overflow: "hidden",
      }}
    >
      {/* Background glow effects to make it feel highly designed */}
      {accentGlow && !transparentBackground && (
        <>
          <div
            style={{
              position: "absolute",
              top: "-10%",
              right: "-10%",
              width: "60%",
              height: "40%",
              background: `radial-gradient(circle, ${accentColor}15 0%, transparent 70%)`,
              filter: "blur(60px)",
              pointerEvents: "none",
              transition: "none",
            }}
          />
          <div
            style={{
              position: "absolute",
              bottom: "5%",
              left: "-10%",
              width: "70%",
              height: "45%",
              background: `radial-gradient(circle, ${accentColor}0D 0%, transparent 70%)`,
              filter: "blur(80px)",
              pointerEvents: "none",
              transition: "none",
            }}
          />
        </>
      )}

      {/* Slide 1 Container */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          padding: `0 ${width * 0.07}px`,
          justifyContent: "center",
          opacity: slide1ExitOpacity,
          transform: `translateY(${slide1ExitY}px)`,
          transition: "none",
        }}
      >
        {/* Title Block */}
        <div
          style={{
            opacity: title1Opacity,
            transform: `translateY(${title1TranslateY}px)`,
            marginBottom: 48,
            transition: "none",
          }}
        >
          <div
            style={{
              fontSize: 20,
              textTransform: "uppercase",
              letterSpacing: "4px",
              color: accentColor,
              fontWeight: "800",
              marginBottom: 16,
              transition: "none",
            }}
          >
            THE PROBLEM
          </div>
          <h1
            style={{
              fontSize: 54,
              fontWeight: "800",
              color: titleColor,
              lineHeight: "1.2",
              margin: 0,
              transition: "none",
            }}
          >
            {titleText}
          </h1>
        </div>

        {/* Stack Grid of Cards - Increased gap for bigger points */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 32,
            width: "100%",
            transition: "none",
          }}
        >
          {renderBox(point1Text, FolderIcon, p1Spring)}
          {renderBox(point2Text, TemplateIcon, p2Spring)}
          {renderBox(point3Text, ScrambleIcon, p3Spring)}
          {renderBox(point4Text, GuessingIcon, p4Spring)}
        </div>
      </div>

      {/* Slide 2 Container */}
      {frame >= slideTransitionStart && (
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            padding: `0 ${width * 0.08}px`,
            opacity: slide2EntryOpacity,
            transform: `translateY(${slide2EntryY}px)`,
            transition: "none",
          }}
        >
          {/* Bold typographic solutions blocks */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 80,
              width: "100%",
              textAlign: "center",
              zIndex: 1,
              transition: "none",
            }}
          >
            {/* Slide 2 Line 1 */}
            <div
              style={{
                opacity: s2Line1Opacity,
                transform: `scale(${s2Line1Scale})`,
                transition: "none",
              }}
            >
              <div
                style={{
                  fontSize: 18,
                  textTransform: "uppercase",
                  letterSpacing: "5px",
                  color: "#94A3B8",
                  fontWeight: "700",
                  marginBottom: 16,
                  transition: "none",
                }}
              >
                THE TRUTH
              </div>
              <p
                style={{
                  fontSize: 58,
                  fontWeight: "700",
                  lineHeight: "1.3",
                  margin: 0,
                  transition: "none",
                }}
              >
                {renderHighlightedText(slide2Text1)}
              </p>
            </div>

            {/* Subtle dividing line */}
            <div
              style={{
                width: 80,
                height: 4,
                backgroundColor: `${accentColor}33`,
                alignSelf: "center",
                borderRadius: 2,
                opacity: s2Line2Opacity,
                transition: "none",
              }}
            />

            {/* Slide 2 Line 2 */}
            <div
              style={{
                opacity: s2Line2Opacity,
                transform: `scale(${s2Line2Scale})`,
                transition: "none",
              }}
            >
              <div
                style={{
                  fontSize: 18,
                  textTransform: "uppercase",
                  letterSpacing: "5px",
                  color: "#94A3B8",
                  fontWeight: "700",
                  marginBottom: 16,
                  transition: "none",
                }}
              >
                THE SOLUTION
              </div>
              <p
                style={{
                  fontSize: 58,
                  fontWeight: "700",
                  lineHeight: "1.3",
                  margin: 0,
                  transition: "none",
                }}
              >
                {renderHighlightedText(slide2Text2)}
              </p>
            </div>
          </div>
        </div>
      )}
    </AbsoluteFill>
  );
};

export default AuditAnimation;